from typing import List

from pydantic import BaseModel, Field

from graph.events import log_transition
from services.llm import complete, extract_json


class Plan(BaseModel):
    """Validate the steps generated by the Planner agent."""

    steps: List[str] = Field(min_length=1, max_length=6)


def planner_node(state: dict) -> dict:
    """Create and validate a plan for the user's goal."""

    # Log Planner execution.
    log_transition("planner", state)

    # Get messages from the current state.
    messages = state.get("messages") or []

    if not messages:
        raise ValueError("Cannot create a plan without a user message.")

    # Find the latest user message.
    user_goal = ""

    for message in reversed(messages):
        if message.get("role") == "user":
            user_goal = message.get("content", "").strip()
            break

    if not user_goal:
        raise ValueError("Cannot create a plan without a valid user goal.")

    # Prepare the planning prompt.
    prompt = f"""
You are the Planner agent in a multi-agent workflow.

Break the user's goal into 1 to 6 short, concrete, logically ordered steps.

Requirements:
- Each step must describe a clear action.
- Steps must be relevant to the user's goal.
- Put steps in the correct execution order.
- Return only a valid JSON object.
- Do not include Markdown or explanations outside the JSON.

Use exactly this format:
{{"steps": ["step one", "step two"]}}

User goal:
{user_goal}
"""

    # Generate the plan.
    response = complete(prompt)

    # Extract and validate the JSON response.
    parsed_data = extract_json(response)
    plan = Plan.model_validate(parsed_data)

    # Remove surrounding whitespace from each step.
    cleaned_steps = [step.strip() for step in plan.steps]

    # Reject empty steps.
    if any(not step for step in cleaned_steps):
        raise ValueError("The generated plan contains an empty step.")

    # Return the validated plan and initialize execution.
    return {
        "plan": cleaned_steps,
        "current_step": 0,
    }


def needs_planning(state: dict) -> bool:
    """Determine whether the user's request needs a multi-step plan."""

    # Get messages from the current state.
    messages = state.get("messages") or []

    if not messages:
        return False

    # Find the latest user message.
    user_goal = ""

    for message in reversed(messages):
        if message.get("role") == "user":
            user_goal = message.get("content", "").strip()
            break

    if not user_goal:
        return False

    text = user_goal.lower()
    word_count = len(text.split())

    # Common indicators of simple requests.
    simple_signals = (
        "calculate",
        "what is",
        "what's",
        "search for",
        "look up",
    )

    # Keep short, straightforward requests on the simple path.
    if word_count <= 12 and any(
        signal in text for signal in simple_signals
    ):
        return False

    # Other requests use the Planner agent.
    return True
